<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { onBeforeRouteLeave, useRoute, useRouter } from 'vue-router'
import { NButton, NCheckbox, NInput, NInputNumber, NSelect } from 'naive-ui'
import { agentApi, listAgentSources, type AgentDetail, type CapabilityCatalog, type Revision, type Validation, type Operation, type Agent } from '../agents/api'
import { uniqueTaskTemplates, templateChoiceId } from '../model-management/templates'
import { modelApi, memberError, type TaskPlan, type FixedTemplate } from '../model-management/api'
import { client } from '../../shared/api/client'
import { environment, loadEnvironment } from '../../shared/environment'
import type { Source } from '../../shared/api/types'
import ErrorBanner from '../../shared/ui/ErrorBanner.vue'
import EmptyState from '../../shared/ui/EmptyState.vue'
import MediaPlayer from '../../shared/media/MediaPlayer.vue'
import RegionEditor from '../../shared/media/RegionEditor.vue'
import { newGroup, bindings, selectSources, copyForNewTask, taskInputs, isSingleInput, cleanTaskName, draftIssue, retryKey, planningSignature, taskMode, type Config, type Channel } from './state'
import './task-create.css'
const route=useRoute(),router=useRouter(),step=ref(0),name=ref(''),description=ref(''),config=ref<Config>({schema_version:'1.0',channels:[newGroup()]})
const sources=ref<Source[]>([]),catalog=ref<CapabilityCatalog|null>(null),agents=ref<Agent[]>([]),busy=ref(false),loading=ref(true),error=ref(''),catalogError=ref(''),sourceError=ref(''),notice=ref(''),loadError=ref('')
const agent=ref<AgentDetail|null>(null),revision=ref<Revision|null>(null),validation=ref<Validation|null>(null),operation=ref<Operation|null>(null),confirmed=ref(false),reviewed=ref(false),selectedGroup=ref(0),activeSource=ref(''),copyId=ref<string|null>(null)
const copyDetail=ref<AgentDetail|null>(null),copyInput=ref<string|null>(null)
const templates=ref<FixedTemplate[]>([]),planInputs=reactive<Record<string,string>>({}),planResults=reactive<Record<string,TaskPlan>>({})
const pending=reactive<Record<string,boolean>>({}),saved=ref(''),evaluated=ref('')
const signature=computed(()=>JSON.stringify({name:name.value,description:description.value,config:config.value})),dirty=computed(()=>signature.value!==saved.value),current=computed(()=>config.value.channels?.[selectedGroup.value]),demo=computed(()=>environment.value?.data_origin==='mock'),hasPending=computed(()=>Object.values(pending).some(Boolean))
const legacyMulti=computed(()=>!isSingleInput(config.value))
const copyOptions=computed(()=>copyDetail.value?taskInputs(copyDetail.value.latest_revision.config).map(v=>({value:v.key,label:`${sources.value.find(s=>s.id===v.binding.source_id)?.name??v.binding.source_id} · ${v.channel.name}`})):[])
const copyReady=computed(()=>!!copyDetail.value&&(copyOptions.value.length===1||!!copyInput.value||(!copyOptions.value.length&&copyDetail.value.latest_revision.config.channels?.length===1)))
const templateOptions=computed(()=>uniqueTaskTemplates(templates.value).map(t=>({label:t.name,value:t.id})))
const frozen=computed(()=>legacyMulti.value||busy.value||!!operation.value||revision.value?.state==='published'||!!loadError.value)
const sourceOptions=computed(()=>sources.value.map(s=>({label:`${s.name} · ${s.kind==='file'?'录像':'直播'}`,value:s.id})))
const previewSource=computed(()=>sources.value.find(s=>s.id===activeSource.value))
const validEvaluation=computed(()=>validation.value?.verdict==='executable'&&evaluated.value===signature.value&&Date.parse(validation.value.expires_at)>Date.now())
const canStart=computed(()=>!legacyMulti.value&&validEvaluation.value&&confirmed.value&&!busy.value&&!hasPending.value&&!operation.value)
const blockReason=computed(()=>hasPending.value?'请先保存正在绘制的区域。':!validEvaluation.value?'请先验证当前完整配置为可执行。':!confirmed.value?'请核对最终配置并勾选确认。':'')
const business:Record<string,string>={person:'人员',vehicle:'车辆',intrusion:'进入区域',dwell:'区域停留',absence:'缺员 / 离岗',fire:'火源',presence:'出现检测',visual_subject:'视觉对象',multimodal_observation:'多模态任务判断'}
const label=(v:string)=>business[v]??v
const verdictLabel=(v:string)=>({executable:'可执行',clarification_required:'需要补充条件',unsupported:'暂不支持',insufficient_evidence:'证据不足'} as Record<string,string>)[v]??v
const statusLabel=(v:string)=>({pending:'已受理',running:'处理中',succeeded:'启动完成',partial_failed:'部分启动失败',failed:'启动失败',canceled:'已取消'} as Record<string,string>)[v]??v
const refKey=(value:unknown)=>JSON.stringify(value)
function capability(c:Channel){return catalog.value?.items.find(i=>refKey(i.reference)===refKey(c.capability_ref))}
function selectedTemplate(c:Channel){return templates.value.find(t=>refKey(t.capability_ref)===refKey(c.capability_ref)&&t.target===c.target&&t.rule===c.rule)}
function chooseTemplate(c:Channel,key:string|null){const t=templates.value.find(t=>t.id===key);c.execution_plan=null;c.capability_ref=t?.capability_ref??null;c.target=t?.target??'';c.rule=t?.rule??'';c.requirement_text=t?.name??'';c.task_mode='template'}
function switchMode(c:Channel,mode:'template'|'natural_language'){if(taskMode(c)===mode)return;c.task_mode=mode;c.execution_plan=null;c.capability_ref=null;c.target='';c.rule='';c.requirement_text='';delete planResults[c.channel_id!]}
function trackPlans(){for(const c of config.value.channels??[])if(c.execution_plan)planInputs[c.channel_id!]=planningSignature(c)}

function changeSource(c:Channel,id:string|null){const ids=id?[id]:[];if(bindings(c).filter(b=>!ids.includes(b.source_id)).some(b=>pending[`${c.channel_id}:${b.source_id}`])){error.value='请先完成或撤销当前视频正在绘制的区域。';return}selectSources(c,ids);activeSource.value=id??''}
async function selectCopy(id:string|null){copyId.value=id;copyDetail.value=null;copyInput.value=null;if(!id)return;busy.value=true;try{const value=await agentApi.detail(id);copyDetail.value=value;const choices=taskInputs(value.latest_revision.config);if(choices.length===1)copyInput.value=choices[0]!.key}catch(e){error.value=memberError(e)}finally{busy.value=false}}
let stopped=false,pollTimer:ReturnType<typeof setTimeout>|undefined,allowLeave=false
watch(signature,()=>{validation.value=null;evaluated.value='';confirmed.value=false;reviewed.value=false})
watch(()=>config.value.channels?.map(c=>planningSignature(c)),()=>{for(const c of config.value.channels??[])if(c.execution_plan&&planInputs[c.channel_id!]&&planInputs[c.channel_id!]!==planningSignature(c)){c.execution_plan=null;delete planResults[c.channel_id!]}},{flush:'sync'})
watch(selectedGroup,()=>{activeSource.value=current.value?bindings(current.value)[0]?.source_id??'':''})
watch(step,()=>{error.value=''})
async function loadCatalog(){try{const [value,presets]=await Promise.all([agentApi.catalog(),modelApi.templates()]);catalog.value=value;templates.value=presets.items;catalogError.value=''}catch(e){catalog.value=null;catalogError.value=memberError(e)}}
async function loadSources(){try{sources.value=await listAgentSources();sourceError.value=''}catch(e){sourceError.value=memberError(e)}}
async function loadDraft(){loadError.value='';if(!route.query.draft)return;try{const value=await agentApi.detail(String(route.query.draft));agent.value=value;revision.value=value.latest_revision;name.value=value.name;description.value=value.description;config.value=JSON.parse(JSON.stringify(value.latest_revision.config)) as Config;if(!config.value.channels?.length)config.value.channels=[newGroup()];if(legacyMulti.value){copyId.value=value.id;copyDetail.value=value;copyInput.value=null}trackPlans();await Promise.resolve();saved.value=signature.value;if(revision.value?.state==='published'&&revision.value.latest_validation_id){validation.value=await agentApi.validation(revision.value.latest_validation_id);evaluated.value=signature.value;confirmed.value=true}notice.value=value.latest_revision.state==='published'?'配置已发布，请在智能体详情核对运行状态。':'已恢复服务端草稿。'}catch(e){loadError.value=memberError(e)}}
async function recoverCreate(){
  if(route.query.draft)return
  const raw=sessionStorage.getItem('vision.create.new');if(!raw)return
  try{const pendingRequest=JSON.parse(raw) as {signature:string;key:string};const body=JSON.parse(pendingRequest.signature) as {name:string;description:string;config:Config};if(!body.name||!body.config?.channels||!pendingRequest.key)return;name.value=body.name;description.value=body.description;config.value=body.config;agent.value=await agentApi.create(body,pendingRequest.key);revision.value=agent.value.latest_revision;sessionStorage.removeItem('vision.create.new');saved.value=signature.value;await router.replace({path:'/create',query:{draft:agent.value.id}});notice.value='已恢复上次中断的创建请求，未重复创建实例。'}catch(e){error.value=displayError(e)}
}
async function loadAgents(){try{agents.value=(await agentApi.list()).items}catch{/* optional copy source */}}
async function copyTask(){if(!copyReady.value||!copyDetail.value)return;if(dirty.value&&name.value&&!window.confirm('替换当前未保存输入？'))return;busy.value=true;try{const value=copyDetail.value;const next=copyForNewTask(value.latest_revision.config,copyInput.value);agent.value=null;revision.value=null;operation.value=null;name.value=cleanTaskName(value.name).slice(0,160);description.value=value.description;config.value=next;selectedGroup.value=0;activeSource.value=bindings(next.channels![0]!)[0]?.source_id??'';saved.value='';await router.replace({path:'/create'});notice.value='已使用所选视频的任务条件，新任务只检测这一路视频。'}catch(e){error.value=displayError(e)}finally{busy.value=false}}
async function seed(){busy.value=true;error.value='';try{await agentApi.seed();await Promise.all([loadSources(),loadCatalog(),loadAgents()]);notice.value='已加载模拟录像和直播，仅用于演示配置流程。'}catch(e){error.value=memberError(e)}finally{busy.value=false}}
async function planCurrent(){if(legacyMulti.value)return;const c=current.value;if(!c?.requirement_text.trim())return;busy.value=true;error.value='';try{c.task_mode='natural_language';const result=await modelApi.plan(c);planInputs[c.channel_id!]=planningSignature(result.channel);const index=config.value.channels!.indexOf(c);config.value.channels!.splice(index,1,result.channel);planResults[result.channel.channel_id!]=result;notice.value=result.reason}catch(e){error.value=memberError(e)}finally{busy.value=false}}

async function persist():Promise<Revision>{
  const issue=draftIssue(name.value,config.value,hasPending.value);if(issue)throw new Error(issue)
  if(!agent.value){const body={name:name.value,description:description.value,config:config.value};agent.value=await agentApi.create(body,retryKey('new',body));revision.value=agent.value.latest_revision;sessionStorage.removeItem('vision.create.new')}
  else{const latest=await agentApi.detail(agent.value.id);if(!revision.value)throw Error('草稿状态缺失，请刷新后重试。');if(latest.name!==name.value||latest.description!==description.value){if(latest.row_version!==agent.value.row_version)throw Error('任务信息已被其他页面修改，请刷新并核对。');agent.value=await agentApi.rename(latest.id,{name:name.value,description:description.value,row_version:latest.row_version})}if(JSON.stringify(latest.latest_revision.config)!==JSON.stringify(config.value))revision.value=await agentApi.save(revision.value,config.value);else revision.value=latest.latest_revision;agent.value=await agentApi.detail(agent.value.id)}
  saved.value=signature.value;await router.replace({path:'/create',query:{draft:agent.value.id}});return revision.value!
}
function displayError(e:unknown){return e instanceof Error&&!('response' in e)?e.message:memberError(e)}
async function saveDraft(){if(busy.value)return;busy.value=true;error.value='';try{await persist();notice.value='草稿已保存，可通过当前页面地址继续编辑。'}catch(e){error.value=displayError(e)}finally{busy.value=false}}
async function evaluate(){if(busy.value||legacyMulti.value)return;if(config.value.channels?.some(c=>taskMode(c)==='natural_language'&&!c.execution_plan)){error.value='请先为每个自然语言通道生成执行方案。';return}if(!reviewed.value){error.value='请先核对原始需求与全部结构化条件。';return}busy.value=true;error.value='';try{const r=await persist();const result=await agentApi.validate(r);revision.value=await client.get<Revision>(`/revisions/${encodeURIComponent(r.id)}`).then(r=>r.data);validation.value=result;evaluated.value=signature.value;confirmed.value=false;step.value=3}catch(e){error.value=displayError(e)}finally{busy.value=false}}
async function poll(){if(stopped||!agent.value||!operation.value)return;try{operation.value=await agentApi.operation(agent.value.id,operation.value.id);if(['pending','running'].includes(operation.value.state))pollTimer=setTimeout(()=>void poll(),1000);else if(operation.value.state==='succeeded'){const workspace=await agentApi.workspace(agent.value.id);notice.value=`启动完成，运行 ID：${workspace.runs.filter(r=>r.revision_id===revision.value?.id).map(r=>r.id).join('、')}`;allowLeave=true;await router.push(`/agents/${agent.value.id}/live`)}}catch(e){error.value=memberError(e)}}
async function start(){if(legacyMulti.value)return;if(!canStart.value||!agent.value||!revision.value||!validation.value)return;busy.value=true;error.value='';try{if(revision.value.state==='draft')revision.value=await agentApi.confirm(revision.value,validation.value,retryKey(`confirm:${revision.value.id}`,validation.value));const body={revision_id:revision.value.id,channel_ids:(revision.value.config.channels??[]).map(c=>c.channel_id!),expected_active_run_ids:[]};operation.value=await agentApi.submit(agent.value.id,'start',body,retryKey(`start:${agent.value.id}`,body));sessionStorage.setItem(`vision.create.operation.${agent.value.id}`,operation.value.id);notice.value='启动请求已受理，正在查询各视频的操作结果。';void poll()}catch(e){error.value=displayError(e)}finally{busy.value=false}}
async function reset(){if(busy.value)return;if(dirty.value&&!window.confirm('放弃当前未保存输入？'))return;allowLeave=true;sessionStorage.removeItem('vision.create.new');await router.push('/create');window.location.reload()}
function beforeUnload(event:BeforeUnloadEvent){if(dirty.value){event.preventDefault();event.returnValue=''}}
onBeforeRouteLeave(()=>allowLeave||!dirty.value||window.confirm('有未保存输入，确定离开？'))
onMounted(async()=>{window.addEventListener('beforeunload',beforeUnload);await Promise.all([loadEnvironment(),loadSources(),loadCatalog(),loadAgents()]);await loadDraft();await recoverCreate();if(!route.query.draft)saved.value=signature.value;if(agent.value){const id=sessionStorage.getItem(`vision.create.operation.${agent.value.id}`);if(id)try{operation.value=await agentApi.operation(agent.value.id,id);void poll()}catch{notice.value='未能恢复操作查询，请在智能体详情核对运行状态。'}}loading.value=false})
onBeforeUnmount(()=>{stopped=true;clearTimeout(pollTimer);window.removeEventListener('beforeunload',beforeUnload)})
</script>
<template>
<div class="page-heading"><div><h1>任务创建</h1><p>选择一个监控源或上传的视频，再配置检测任务。</p></div><div class="create-actions"><NButton v-if="demo" :disabled="busy" @click="seed">加载模拟素材</NButton><NButton :disabled="busy" @click="reset">新建另一任务</NButton></div></div>
<div v-if="demo" class="notice">演示模式：解析、校验、运行与报警均为模拟，不代表识别效果。固定模板可直接配置；自然语言优先匹配模板，无法匹配时使用已绑定的模拟多模态大模型。</div>
<ErrorBanner :error="loadError" @retry="loadDraft"/><ErrorBanner :error="error" :retryable="false"/><p v-if="notice" class="notice" role="status">{{notice}}</p><div v-if="loading" class="loading-line"/>
<nav class="create-steps" aria-label="任务创建步骤"><button v-for="(title,index) in ['检测视频与区域','任务模式与条件','执行方案','确认与启动']" :key="title" :aria-current="step===index?'step':undefined" :class="{active:step===index}" :disabled="busy||hasPending||legacyMulti" @click="step=index"><span>{{index+1}}</span>{{title}}</button></nav>
<div class="create-layout"><section class="panel create-main">
<div v-if="legacyMulti" class="notice" role="status">此历史配置包含多路视频。请在下方明确选择本次要检测的一路，复制为单视频任务；原配置会保留。<RouterLink v-if="agent" :to="`/agents/${agent.id}/config`">查看原配置</RouterLink></div>
<div v-if="(!agent&&step===0)||legacyMulti" class="create-copy-panel"><label>可选：使用已有任务的条件</label><div class="create-copy"><NSelect :value="copyId" :options="agents.map(a=>({label:cleanTaskName(a.name),value:a.id}))" placeholder="选择已有任务" aria-label="从已有智能体复制" :disabled="busy" @update:value="selectCopy"/><NSelect v-if="copyOptions.length>1" v-model:value="copyInput" :options="copyOptions" placeholder="选择本次要检测的一路视频" aria-label="复制哪一路视频" :disabled="busy"/><NButton :disabled="busy||!copyReady" @click="copyTask">使用配置</NButton></div></div>
<fieldset v-if="!legacyMulti" :disabled="frozen" class="create-fields">
<template v-if="step===0"><h2>选择检测视频与分析范围</h2><p class="create-hint">每个任务只检测一路视频，可选择监控源或已上传的录像。</p>
<div class="field"><label>任务名称</label><NInput v-model:value="name" :disabled="frozen" :maxlength="160" aria-label="任务名称" :input-props="{'aria-label':'任务名称'}" placeholder="例如：北门区域停留监测"/></div><div class="field"><label>说明（可选）</label><NInput v-model:value="description" :disabled="frozen" :maxlength="2000" aria-label="任务说明" :input-props="{'aria-label':'任务说明'}"/></div>
<template v-if="current"><ErrorBanner :error="sourceError" @retry="loadSources"/><div class="field"><label>选择一个监控源或已上传视频</label><NSelect filterable clearable :value="bindings(current)[0]?.source_id??null" :options="sourceOptions" :disabled="frozen" aria-label="检测视频" @update:value="changeSource(current!, $event)"/><p class="create-hint">需要新的视频？<RouterLink to="/sources">前往视频源管理上传或接入</RouterLink></p></div><EmptyState v-if="!sources.length&&!sourceError" title="还没有视频源" description="请先导入录像或登记摄像头。"><RouterLink to="/sources">前往视频源管理</RouterLink></EmptyState>
<section v-for="b in bindings(current)" :key="current.channel_id+':'+b.source_id" class="create-source"><div class="panel-title"><h3>{{sources.find(s=>s.id===b.source_id)?.name??b.source_id}}</h3><NButton size="tiny" @click="activeSource=activeSource===b.source_id?'':b.source_id">{{activeSource===b.source_id?'关闭预览':'预览'}}</NButton></div><p class="create-hint">{{sources.find(s=>s.id===b.source_id)?.width??'未知'}} × {{sources.find(s=>s.id===b.source_id)?.height??'未知'}} · {{sources.find(s=>s.id===b.source_id)?.fps??'未知'}} fps · {{sources.find(s=>s.id===b.source_id)?.duration_ms!=null?`${sources.find(s=>s.id===b.source_id)!.duration_ms!/1000} 秒`:'直播或时长未知'}}</p>
<template v-if="activeSource===b.source_id&&previewSource"><div v-if="demo" class="create-mock">模拟视频素材 · 仅用于配置练习</div><MediaPlayer v-else :key="b.source_id" :source="previewSource"/></template>
<div v-if="sources.find(s=>s.id===b.source_id)?.kind==='file'" class="field-grid"><div class="field"><label>录像开始位置（秒）</label><NInputNumber :value="b.start_media_ms==null?null:b.start_media_ms/1000" :disabled="frozen" :min="0" :precision="3" aria-label="录像开始秒" :input-props="{'aria-label':'录像开始秒'}" @update:value="b.start_media_ms=$event==null?null:Math.round($event*1000)"/></div><div class="field"><label>录像结束位置（秒）</label><NInputNumber :value="b.end_media_ms==null?null:b.end_media_ms/1000" :disabled="frozen" :min="0" :precision="3" aria-label="录像结束秒" :input-props="{'aria-label':'录像结束秒'}" @update:value="b.end_media_ms=$event==null?null:Math.round($event*1000)"/></div></div>
<RegionEditor :key="current.channel_id+':'+b.source_id" :source="sources.find(s=>s.id===b.source_id)" :regions="b.regions??[]" :demo="demo" :disabled="frozen" @change="b.regions=$event" @pending="pending[`${current!.channel_id}:${b.source_id}`]=$event"/>
</section></template></template>
<template v-else-if="step===1">
<h2>选择任务模式并补充条件</h2><template v-if="current"><div class="task-mode-options" role="group" aria-label="任务模式"><button type="button" aria-label="固定模板模式" :disabled="frozen" :aria-pressed="taskMode(current)==='template'" :class="{selected:taskMode(current)==='template'}" @click="switchMode(current!,'template')"><strong>固定模板</strong><span>直接选择检测火源、人员进入区域等已有任务。</span></button><button type="button" aria-label="自然语言任务模式" :disabled="frozen" :aria-pressed="taskMode(current)==='natural_language'" :class="{selected:taskMode(current)==='natural_language'}" @click="switchMode(current!,'natural_language')"><strong>自然语言任务</strong><span>先匹配已有模板；无法匹配则由多模态大模型分析并执行。</span></button></div>
<template v-if="taskMode(current)==='template'"><ErrorBanner :error="catalogError" @retry="loadCatalog"/><div class="field"><label>选择固定模板</label><NSelect :value="templateChoiceId(templates,selectedTemplate(current))" :options="templateOptions" :disabled="frozen" clearable aria-label="固定任务模板" @update:value="chooseTemplate(current!,$event)"/></div><EmptyState v-if="!templates.length&&!catalogError" title="暂无可用固定模板" description="可以切换到自然语言模式，由已部署的多模态大模型生成方案。"/><div v-if="selectedTemplate(current)" class="create-assessment"><strong>{{selectedTemplate(current)!.name}}</strong><p>对象：{{label(current.target)}} · 规则：{{label(current.rule)}}</p><p>{{selectedTemplate(current)!.requires_region?'请为所选视频绘制区域。':'此模板不强制要求区域。'}} {{selectedTemplate(current)!.requires_duration?'请明确持续时长。':''}}</p><ul><li v-for="v in selectedTemplate(current)!.limitations" :key="v">{{v}}</li></ul></div></template>
<template v-else><div class="field"><label>用自然语言发布监测任务</label><NInput v-model:value="current.requirement_text" :disabled="frozen" type="textarea" :maxlength="8000" :autosize="{minRows:4}" aria-label="监测需求" :input-props="{'aria-label':'监测需求'}" placeholder="例如：检测是否有穿红色衣服的人进入区域"/></div><div class="planning-route"><span>① 优先匹配已有模板</span><span>② 无法完整匹配 → 多模态大模型分析</span><span>③ 按确定的执行方案运行任务</span></div><NButton type="primary" :disabled="frozen||!current.requirement_text.trim()" @click="planCurrent">生成执行方案</NButton><p class="create-hint">系统保留完整需求，不会把额外条件删掉后当作模板匹配成功。补充条件后请重新生成方案。</p><div v-if="current.execution_plan" class="create-assessment" data-testid="execution-plan"><strong>{{current.execution_plan.executor_kind==='template'?'已匹配已有模板':'由多模态大模型执行'}}</strong><p>{{current.execution_plan.reason}}</p><p v-if="planResults[current.channel_id!]">方案检查：{{verdictLabel(planResults[current.channel_id!].verdict)}}</p><p v-if="current.execution_plan.executor_kind==='multimodal'">执行模型：{{current.execution_plan.deployment_id}} · {{current.execution_plan.deployment_version}}</p><p v-if="current.execution_plan.instruction">完整任务指令：{{current.execution_plan.instruction}}</p><ul><li v-for="v in [...(planResults[current.channel_id!]?.missing_conditions??[]),...(current.execution_plan.limitations??[])]" :key="v">{{v}}</li></ul></div><p v-else class="notice">尚未生成当前需求的执行方案。模板匹配失败会进入多模态路径，不要求你强选一个模板。</p></template>
<div class="field"><label>触发条件持续时长（秒，仅在任务需要时填写）</label><NInputNumber v-model:value="current.duration_seconds" :disabled="frozen" :min="1" :max="86400" :precision="0" aria-label="持续时长" :input-props="{'aria-label':'持续时长'}"/></div>
</template><EmptyState v-else title="请先选择检测视频"/></template>
<template v-else-if="step===2"><h2>核对执行方案</h2>
<section v-for="(c,index) in config.channels" :key="c.channel_id" class="create-source"><h3>{{sources.find(s=>s.id===bindings(c)[0]?.source_id)?.name??'本次检测视频'}}</h3><p class="create-hint">任务内容：{{c.requirement_text||'尚未选择模板或填写需求'}}</p>
<template v-if="taskMode(c)==='template'"><strong>固定模板执行</strong><p>{{selectedTemplate(c)?.name??'尚未选择模板'}}</p><p v-if="c.capability_ref">模型 {{c.capability_ref.model_id}} @ {{c.capability_ref.model_version}} · 模板 {{c.capability_ref.template_id}} @ {{c.capability_ref.template_version}}</p><ul><li v-for="v in selectedTemplate(c)?.limitations??[]" :key="v">{{v}}</li></ul></template>
<template v-else-if="c.execution_plan"><strong>{{c.execution_plan.executor_kind==='template'?'自然语言 → 已有模板优先执行':'自然语言 → 多模态大模型执行'}}</strong><p>{{c.execution_plan.reason}}</p><p v-if="c.execution_plan.executor_kind==='multimodal'">执行模型 {{c.execution_plan.deployment_id}} @ {{c.execution_plan.deployment_version}}</p><p v-if="c.execution_plan.instruction">执行指令：{{c.execution_plan.instruction}}</p><ul><li v-for="v in c.execution_plan.limitations" :key="v">{{v}}</li></ul></template><p v-else class="notice">请先生成自然语言执行方案。</p>
<NButton size="small" :disabled="frozen" @click="selectedGroup=index;step=1">返回修改任务</NButton></section></template>
<template v-else><h2>核对最终配置并启动</h2><p class="create-hint">运行绑定配置、模型与模板的具体版本，操作完成后才显示成功。</p><div v-for="c in config.channels" :key="c.channel_id" class="create-source"><h3>{{sources.find(s=>s.id===bindings(c)[0]?.source_id)?.name??'本次检测视频'}}</h3><p>{{c.requirement_text||'原始需求为空'}}</p><dl class="detail-meta"><div><dt>监测条件</dt><dd>{{label(c.target)}} / {{label(c.rule)}} / {{c.duration_seconds==null?'时长未设':`${c.duration_seconds}秒`}}</dd></div><div><dt>视频数量</dt><dd>{{bindings(c).length}}</dd></div><div class="wide"><dt>执行方式与版本快照</dt><dd>{{c.execution_plan?.executor_kind==='multimodal'?`多模态大模型 ${c.execution_plan.deployment_id} @ ${c.execution_plan.deployment_version}`:c.capability_ref?`${c.capability_ref.model_id} @ ${c.capability_ref.model_version} / ${c.capability_ref.template_id} @ ${c.capability_ref.template_version}`:'未生成执行方案'}}</dd></div><div v-for="b in bindings(c)" :key="b.source_id" class="wide"><dt>{{sources.find(s=>s.id===b.source_id)?.name??b.source_id}}</dt><dd>{{b.regions?.length??0}} 个区域 · {{b.start_media_ms==null?'全段 / 直播':`${b.start_media_ms/1000}–${b.end_media_ms!/1000} 秒`}}</dd></div></dl></div></template>
</fieldset><section v-if="!legacyMulti&&step>=2&&!operation" class="create-review"><NCheckbox v-model:checked="reviewed" :disabled="frozen">我已核对本次任务、执行方案和所选视频的全部必要条件。</NCheckbox><NButton type="primary" secondary :loading="busy" :disabled="frozen||!reviewed||hasPending" @click="evaluate">保存并验证可执行性</NButton></section></section>
<aside class="panel create-summary"><span class="create-eyebrow">配置概览</span><h2>{{cleanTaskName(name)||'未命名监测任务'}}</h2><div v-if="!legacyMulti" class="create-summary-numbers"><div><strong>{{current?bindings(current).length:0}}</strong><span>检测视频</span></div></div><p v-if="!legacyMulti&&current">{{sources.find(s=>s.id===bindings(current!)[0]?.source_id)?.name??'尚未选择检测视频'}}</p><p>{{dirty?'有尚未保存的修改':agent?'服务端草稿已保存':'开始配置新任务'}}</p><p v-if="hasPending" class="notice">存在未完成的区域，请先闭合并保存。</p><div v-if="agent" class="create-ids"><span>agentId</span><code>{{agent.id}}</code><span>revisionId</span><code>{{revision?.id}}</code><RouterLink :to="`/agents/${agent.id}/config`">查看智能体配置</RouterLink></div>
<div class="create-assessment" aria-live="polite"><h3>可执行性评估</h3><p v-if="!validation">{{dirty?'配置已变化，需要重新验证。':'尚未验证当前配置。'}}</p><template v-else><strong>{{verdictLabel(validation.verdict)}}</strong><small v-if="validation.data_origin==='mock'">模拟结果</small><ul><li v-for="v in [...(validation.missing_conditions??[]),...(validation.unsupported_conditions??[]),...(validation.evidence_limitations??[])]" :key="v">{{v}}</li></ul><p>有效至 {{new Date(validation.expires_at).toLocaleTimeString()}}</p></template></div>
<template v-if="!legacyMulti&&step===3&&!operation"><NCheckbox v-model:checked="confirmed" :disabled="!validEvaluation||frozen">我确认配置、源范围和能力限制，同意按上述版本启动。</NCheckbox><NButton block type="primary" :loading="busy" :disabled="!canStart" @click="start">确认并启动</NButton><p v-if="blockReason" class="create-hint">{{blockReason}}</p></template>
<div v-if="operation" class="create-assessment"><h3>{{statusLabel(operation.state)}}</h3><p>{{operation.message}}</p><code>{{operation.id}}</code><div v-for="c in operation.channels" :key="c.channel_id+':'+c.source_id" class="create-operation"><span>{{sources.find(s=>s.id===c.source_id)?.name??c.source_id}} · {{statusLabel(c.state)}}</span><p>{{c.message}}</p><code v-if="c.new_run_id">runId: {{c.new_run_id}}</code></div><NButton :disabled="busy" @click="poll">刷新操作状态</NButton><RouterLink v-if="agent" :to="`/agents/${agent.id}/live`">进入智能体详情</RouterLink></div><p v-if="revision?.state==='published'&&!operation" class="notice">配置已发布。可重试上一次启动请求，或到智能体详情核对状态。</p>
</aside></div><footer class="create-footer"><span>{{agent?'草稿已关联智能体':'保存后由智能体服务分配 ID'}}</span><div class="create-actions"><NButton :disabled="frozen||hasPending" :loading="busy" @click="saveDraft">保存草稿</NButton><NButton :disabled="busy||hasPending||step===0" @click="step--">上一步</NButton><NButton v-if="step<3" type="primary" :disabled="busy||hasPending||legacyMulti" @click="step++">下一步</NButton><NButton v-if="agent" @click="router.push(`/agents/${agent.id}/config`)">查看已保存配置</NButton></div></footer>
</template>
